import{obterJSON,endereco,consultaLimpa,pontuarCorrespondencia,idiomas}from'./comum.js';
const nsDc='http://purl.org/dc/elements/1.1/';
const textos=(el,nome)=>[...el.getElementsByTagNameNS(nsDc,nome)].map(x=>x.textContent?.trim()).filter(Boolean);
export function converterGallica(rec){const ids=textos(rec,'identifier'),ark=ids.find(x=>/gallica\.bnf\.fr\/ark:\/12148\//i.test(x))||ids.find(x=>/ark:\/12148\//i.test(x));if(!ark)return null;const ler=endereco(ark.startsWith('http')?ark:`https://gallica.bnf.fr/${ark.replace(/^\//,'')}`);if(!ler)return null;return{id:`gallica:${ler}`,fonte:'gallica',provedor:'Gallica · BnF',titulo:textos(rec,'title')[0]||'Sem título',autores:textos(rec,'creator'),idiomas:idiomas(textos(rec,'language')),capa:null,descricao:textos(rec,'description')[0]||'',acessoLivre:true,dominioPublico:true,tipoAcesso:'Digitalização livre de direitos',licenca:'Resultado do Gallica filtrado pela indicação “libre de droits” da BnF. Consulte a página da obra para as condições de reutilização.',origem:ler,ler,texto:null,formatos:[]}}
export async function pesquisarGallica(q,o={}){const termo=consultaLimpa(q);if(!termo)return{livros:[],total:0,temMais:false};const pagina=Math.max(1,o.pagina||1),u=new URL('/api/acervos-gratuitos',location.origin);u.searchParams.set('fonte','gallica');u.searchParams.set('q',termo);u.searchParams.set('pagina',String(pagina));const d=await obterJSON(u,14000,2),doc=new DOMParser().parseFromString(String(d?.xml||''),'application/xml');if(doc.querySelector('parsererror'))throw new Error('Gallica devolveu XML inválido');const registros=[...doc.getElementsByTagNameNS('*','record')],livros=registros.map(converterGallica).filter(Boolean);for(const l of livros)l.relevancia=pontuarCorrespondencia(termo,l.titulo,l.autores);livros.sort((a,b)=>(b.relevancia||0)-(a.relevancia||0));const no=[...doc.getElementsByTagNameNS('*','numberOfRecords')][0],total=Number(no?.textContent)||livros.length;return{livros,total,temMais:pagina*20<total&&registros.length>0}}
